<?php
 namespace Pterodactyl\Services\Dezerx; use Throwable; use Pterodactyl\Contracts\Repository\SettingsRepositoryInterface; class Settings { private const PREFIX = 'settings::dezerx:'; private static array $cache = []; public static function get(string $key): ?array { if (array_key_exists($key, self::$cache)) { return self::$cache[$key]; } try { $raw = app(SettingsRepositoryInterface::class)->get(self::PREFIX . $key, null); } catch (Throwable) { return self::$cache[$key] = null; } if (!is_string($raw) || $raw === '') { return self::$cache[$key] = null; } $decoded = json_decode($raw, true); return self::$cache[$key] = is_array($decoded) ? $decoded : null; } public static function put(string $key, array $value): void { app(SettingsRepositoryInterface::class)->set( self::PREFIX . $key, json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), ); self::$cache[$key] = $value; } public static function forget(string $key): void { app(SettingsRepositoryInterface::class)->forget(self::PREFIX . $key); unset(self::$cache[$key]); } } 